core/events/types.ts:
export type AppEvent = {
    type: 'task:start';
    bookId: string;
    stage: CompileStage;
    total: number;
    unit?: '章' | '步骤' | '批' | '窗口';
} | {
    type: 'task:progress';
    bookId: string;
    stage: CompileStage;
    completed: number;
    failed: number;
    total: number;
    cost: number;
} | {
    type: 'task:paused';
    bookId: string;
    stage: CompileStage;
} | {
    type: 'task:resumed';
    bookId: string;
    stage: CompileStage;
} | {
    type: 'task:cancelled';
    bookId: string;
    stage: CompileStage;
} | {
    type: 'task:done';
    bookId: string;
    stage: CompileStage;
    completed: number;
    failed: number;
    pendingFailures?: number;
} | {
    type: 'chapter:start';
    bookId: string;
    chapterIndex: string;
} | {
    type: 'chapter:done';
    bookId: string;
    chapterIndex: string;
    characters: number;
    locations: number;
    nodes: number;
} | {
    type: 'chapter:failed';
    bookId: string;
    chapterIndex: string;
    message?: string;
} | {
    type: 'log';
    level: 'info' | 'warn' | 'error';
    message: string;
    data?: unknown;
};

